const fsrc=document.querySelectorAll('[data-fetch-src]');if(fsrc){function afetch(fs){const p=typeof post_vars!=='undefined'?post_vars:{};const g=Object.fromEntries(new URLSearchParams(window.location.search));const q='?t='+(new Date().getTime());const nc=window.drupalSettings?.csp?.nonce?' nonce = "'+drupalSettings.csp.nonce+'"':'';async function f(s,m){const d=new FormData(),v={};Object.assign(v,(['GET','ALL'].includes(m)?g:{}),(['POST','ALL'].includes(m)?p:{}));Object.keys(v).forEach(k=>d.append(k,v[k]));const r=await fetch(s,(!d.entries().next().done?{method:'POST',body:d,}:{}));return[r.ok,r.ok?await r.text():'[<strong>'+r.status+'</strong> '+r.statusText+' – '+s+']']}
fs.forEach(function(i){const fn=i.getAttribute('data-fn-ok'),em=i.getAttribute('data-errmsg');let m=i.getAttribute('data-method');m=m?m.toUpperCase():'NONE';i.innerHTML='<strong>Fetching content…</strong>';f(i.getAttribute('data-fetch-src')+q,m?m.toUpperCase():'NONE').then(o=>{if(o[0]){i.outerHTML=o[1].replace('<script','<script'+nc).replace('<style','<style'+nc);if(fn&&typeof window[fn]==='function')window[fn]();}else{i.innerHTML=em?em:o[1]}})})}
afetch(fsrc)}
